ink='#213b39'; teal='#337b73'; clay='#a85237'; faint='#dce4df'; sand='#eee6d9'; oak='#dbc29d'; olive='#a9b485'; cream='#faf8f3'; grey='#596863'
def rect(x,y,w,h,fill,stroke=None,lw=.33):
    pdf.setLineWidth(lw*mm);pdf.setFillColor(HexColor(fill));pdf.setStrokeColor(HexColor(stroke or fill))
    pdf.rect(x*mm,(297-y-h)*mm,w*mm,h*mm,fill=1,stroke=bool(stroke))
def line(x,y,X,Y,col=ink,lw=.35,dash=False):
    pdf.setStrokeColor(HexColor(col));pdf.setLineWidth(lw*mm);pdf.setDash([2*mm,1*mm] if dash else []);pdf.line(x*mm,(297-y)*mm,X*mm,(297-Y)*mm);pdf.setDash([])
def txt(x,y,s,sz=11,b=False,col=ink,align='left'):
    pdf.setFont('B' if b else 'R',sz);pdf.setFillColor(HexColor(col))
    getattr(pdf,{'left':'drawString','mid':'drawCentredString','right':'drawRightString'}[align])(x*mm,(297-y)*mm,str(s))
def para(x,y,s,w=115,size=12):
    words=[]
    for word in s.split():
        if words and pdfmetrics.stringWidth(' '.join(words+[word]),'R',size)>w*mm:
            txt(x,y,' '.join(words),size);words=[];y+=size*.49
        words.append(word)
    if words:txt(x,y,' '.join(words),size);y+=size*.49
    return y
def pic(path,x,y,w,h):
    im=Image.open(path); a=min(w/im.width,h/im.height);dw,dh=im.width*a,im.height*a
    pdf.drawImage(str(path),(x+(w-dw)/2)*mm,(297-y-(h+dh)/2)*mm,dw*mm,dh*mm)
titles=['Паспорт и состав выпуска','Обмерный план','Дневная расстановка','Ночная расстановка','Кухня у входа','Развёртки кухни','Медиастена и стеллаж','Рабочий стол и терраса','Скрытая ниша шторы','План пола','Отделка стен','Потолок и свет','Управление и сценарии','Розетки и данные','Вода, вытяжка и отопление','Мебель и оборудование','Два режима в объёме','Контроль перед заказом']
def head(n,sub,title=None):
    title=title or titles[n-1];pdf.bookmarkPage('p'+str(n));pdf.addOutlineEntry(f'{n:02}   {title}','p'+str(n))
    rect(0,0,420,297,cream);txt(13,12,'КВАРТИРА 98     /     МИНСК     /     B01',10,True,teal);txt(407,12,'КООРДИНАЦИОННЫЙ ВЫПУСК   •   К01',10,True,teal,'right')
    txt(13,30,title,29,True);txt(13,40,sub,11,False,grey);line(13,45,407,45,faint)
    line(13,280,407,280,faint);txt(13,289,'B01    /    КУХНЯ-ГОСТИНАЯ     •     18.11.2026     •     РАЗМЕРЫ В МИЛЛИМЕТРАХ',9,True,teal);txt(407,289,f'К01    /    {n:02}',10,True,teal,'right')
def side(items):
    line(267,53,267,260,faint);y=60
    for a,b in items:
        txt(275,y,a,14,True,teal);y=para(275,y+9,b,129,12)+11
    assert y<283,(items,y)
def foot(a,b):
    txt(14,260,a,13,True,teal);para(14,268,b,247,10)
def dim(x,y,X,Y,label):
    line(x,y,X,Y,grey,.2)
    if y==Y:
        for u in [x,X]:line(u-1.4,y+1.5,u+1.4,y-1.5,grey)
        txt((x+X)/2,y-2,label,10,False,grey,'mid')
    else:
        for v in [y,Y]:line(x-1.5,v+1.3,x+1.5,v-1.3,grey)
        pdf.saveState();pdf.translate((x-2)*mm,(297-(y+Y)/2)*mm);pdf.rotate(90);pdf.setFont('R',10);pdf.setFillColor(HexColor(grey));pdf.drawCentredString(0,0,label);pdf.restoreState()
# X от входа вдоль медиастены; Y от медиастены к дивану. Масштаб 1:25 при печати 100%.
px=lambda x:23+x/25
py=lambda y:228-y/25
def seg(x,y,X,Y,*args):line(px(x),py(y),px(X),py(Y),*args)
def box(x,y,w,h,col,lab='',sz=9):
    rect(px(x),py(y+h),w/25,h/25,col,grey,.24)
    if lab:txt(px(x+w/2),py(y+h/2)+1,lab,sz,False,ink,'mid')
def tag(x,y,s,col=clay):
    X,Y=px(x),py(y);w=pdfmetrics.stringWidth(s,'B',10)/mm+3
    rect(X-w/2,Y-2.7,w,5.2,col);txt(X,Y+1.1,s,10,True,'#ffffff','mid')
def swing(x,y,r,sx,sy,col):
    for i in range(0,90,5):
        a=i*pi/180;b=(i+5)*pi/180;seg(x+sx*r*sin(a),y+sy*r*cos(a),x+sx*r*sin(b),y+sy*r*cos(b),col,.17)
    seg(x,y,x+sx*r,y,col,.65)
def shell():
    rect(px(0),py(3500),5710/25,3500/25,'#ffffff')
    for x,y,X,Y in [(0,0,5710,0),(0,3500,5710,3500),(0,0,0,200),(0,1110,0,3500),(5710,0,5710,600),(5710,2200,5710,3500)]:seg(x,y,X,Y,ink,.95)
    seg(5710,600,5710,1400,teal,.55);swing(0,200,910,1,1,teal);swing(5710,2200,800,-1,-1,teal)
    dim(px(0),75,px(5710),75,'5710  B');dim(16,py(3500),16,py(0),'3500  B');txt(23,239,'D2   ВХОД',9,True,teal);txt(251,239,'O1   ТЕРРАСА',9,True,teal,'right')
    txt(22,58,'ПЛАН  1:25    /    A3 · печать 100%',10,True,teal);line(207,58,247,58,ink,.65);txt(227,55,'1000 мм',8,False,grey,'mid')
kit=[(0,2900,600,600,'Угол'),(600,2900,500,600,'500'),(1100,2900,500,600,'Варка'),(1600,2900,200,600,'200'),(1800,2900,600,600,'Пенал'),(0,2330,600,570,'Мойка'),(0,1730,600,600,'ПММ'),(0,1130,600,600,'Хол.')]
def furn(night=False,labels=True,park=False):
    for x,y,w,h,l in kit:box(x,y,w,h,sand,l if labels else '',8)
    pieces=[(2485,1270 if night else 2300,1970,2230 if night else 1200,olive,'Domo PRO 180'),(4500,2900,1200,600,oak,'Рабочий стол'),(2070,0,2800,450,sand,'Тумба 2800'),(4870,0,600,300,oak,'Книги')]
    if not night:pieces += [(2770,1500,1400,800,'#f4e6ce','Стол'),(2880,1100,400,400,sand,''),(3600,1100,400,400,sand,'')]
    if park:pieces += [(1600,1400,800,1400,'#f4e6ce','Стол'),(1500,1460,400,400,sand,''),(1500,2200,400,400,sand,'')]
    for x,y,w,h,c,l in pieces:box(x,y,w,h,c,l if labels else '')
    seg(4870,300,5470,300,teal,.8)
def dot(x,y,col=teal,r=2):
    pdf.setFillColor(HexColor(col));pdf.circle(px(x)*mm,(297-py(y))*mm,r*mm,stroke=0,fill=1)
def table(x,y,widths,headers,rows,step=12,sz=11):
    X=x
    for w,h in zip(widths,headers):rect(X,y,w,10,teal);txt(X+2,y+6.5,h,9,True,'#ffffff');X+=w
    y+=10
    for i,row in enumerate(rows):
        X=x;rect(x,y,sum(widths),step,'#f0eee6' if i%2==0 else '#ffffff')
        for w,s in zip(widths,row):
            bottom=para(X+2,y+5.8,str(s),w-4,sz)
            assert bottom<=y+step+4,(s,y,bottom,step)
            X+=w
        y+=step
    return y
def end():pdf.showPage()
