def elevation(x,y,width,height,divs,k,desc):
    txt(x,y-height*k-6,desc,12,True,teal);rect(x,y-height*k,width*k,height*k,'#f2f0e9',grey)
    for a,z,w,h,col,label in divs:
        rect(x+a*k,y-(z+h)*k,w*k,h*k,col,grey,.25)
        if label:txt(x+(a+w/2)*k,y-(z+h/2)*k+1,label,9,False,ink,'mid')
    dim(x,y+7,x+width*k,y+7,str(width)+' P')
head(6,'Стены Г и А · взгляд от центра комнаты к фасадам · высоты для компоновки P')
def krun(x,ws,labs,tall):
    a=0;ds=[]
    for i,(w,l) in enumerate(zip(ws,labs)):
        ds.append((a,0,w,2700 if i==tall else 900,sand,l))
        if i!=tall:ds.append((a,1500,w,1200,'#f4f0e6',''))
        if l=='Пенал':ds.extend([(a+25,680,w-50,600,'#8c9690','Духовка'),(a+25,1300,w-50,430,'#a2ada8','СВЧ')])
        a+=w
    elevation(x,201,sum(ws),2700,ds,.045,'Г · к входу' if tall==3 else 'А · к дивану')
krun(18,[600,570,600,600],['Угол','Мойка','ПММ','Хол.'],3)
