# Volumetric drawings generated from the same X/Y extents as sheets 03–04.
def axo(cx,cy,night):
    scale=.0185
    def P(x,y,z):return (cx+(x+y*.60)*scale,cy+(y*.40-x*.20-z*.68)*scale)
    def polygon(pts,fill,stroke=grey):
        p=pdf.beginPath()
        for i,(x,y,z) in enumerate(pts):
            u,v=P(x,y,z);(p.moveTo if i==0 else p.lineTo)(u*mm,(297-v)*mm)
        p.close();pdf.setStrokeColor(HexColor(stroke));pdf.setFillColor(HexColor(fill));pdf.setLineWidth(.18*mm);pdf.drawPath(p,fill=1,stroke=1)
    items=[]
    def cube(x,y,w,d,h,col,z=0):
        items.append((x,y,w,d,h,col,z))
    def paint(x,y,w,d,h,col,z):
        polygon([(x,y+d,z),(x+w,y+d,z),(x+w,y+d,z+h),(x,y+d,z+h)],col)
        polygon([(x,y,z),(x,y+d,z),(x,y+d,z+h),(x,y,z+h)],col)
        polygon([(x,y,z+h),(x+w,y,z+h),(x+w,y+d,z+h),(x,y+d,z+h)],col)
    polygon([(0,0,0),(5710,0,0),(5710,3500,0),(0,3500,0)],'#f1e0c9')
    for x,y,w,d,label in kit:cube(x,y,w,d,2700 if label in ['Пенал','Хол.'] else 900,sand)
    cube(4500,2900,1200,600,65,oak,710);cube(4500,3200,1200,300,950,sand,1750)
    cube(2485,1270 if night else 2300,1970,2230 if night else 1200,580,olive)
    cube(2485,3350,1970,150,260,olive,580)
    if not night:cube(2770,1500,1400,800,45,sand,720)
    else:cube(1600,1400,800,1400,45,sand,720)
    cube(4870,0,600,300,2700,oak)
    # Openings on the Y=300 face, looking directly toward the desk.
    cube(2070,0,2800,450,540,sand,150)
    for obj in sorted(items,key=lambda t:t[0]-t[1],reverse=True):
        paint(*obj)
    for z in [380,760,1140,1520,1900]:
        polygon([(4900,302,z),(5440,302,z),(5440,302,z+330),(4900,302,z+330)],'#a88962')
