# Budget reproduces dated source rates; never treats a missing offer as zero.
book=openpyxl.load_workbook(next((ROOM/'Закупки_B01').glob('*.xlsx')),data_only=False)
prices={r[0]:r for r in list(book['Поставщики'].values)[4:]}
inputs=book['Исходные данные']
area=inputs['B4'].value*inputs['B5'].value
purchase=ceil(area*(1+inputs['B7'].value)/inputs['B8'].value)*inputs['B8'].value
cost=[]
for r in list(book['Смета'].values)[5:]:
    code,group,typ,name,unit,qty,inc=r[:7];rates=prices[code];idx=1+4*(r[7]-1)
    vendor,rate,url=rates[idx:idx+3]
    if code=='О01':continue
    if isinstance(qty,str):qty=purchase if 'B9' in qty else area
    amt=round(qty*rate,2) if isinstance(rate,(int,float)) and isinstance(qty,(int,float)) else None
    status='прайс 09.11' if 'ПРАЙС' in str(r[13]) else 'бюджет'
    if code in ('П01','М03','Т03','Т06'):status='оценка/аналог'
    if inc!='Да':amt=None;status='имеется' if inc=='Нет' else 'решить'
    if code in ('М01','Т07'):amt=None;rate=None;status='запрос КП'
    cost.append((code,group,name,qty,unit,rate,amt,status,vendor,url))
extras=[('О1а','Окно и отопление','Somfy Glydea Ultra 35 WT · пример для 2,5 м',1,'компл.',1370,1370,'аналог длины','ENZO','https://www.enzopremium.by/electro/somfy-glydea-irismo.php'),('О1б','Окно и отопление','Канвас OLIS · расчёт 4,5 м',4.5,'м',27,121.5,'сценарий','OLIS','https://olis.by/2227-porternaya-tkan-kanvas'),('О1в','Окно и отопление','Скрытая ниша в общем заказе потолка',2.2,'м',45,99,'цена от','Альфа Потолки','https://www.alfapotolokminsk.by/uslugi/nisha-pod-karniz'),('О1г','Окно и отопление','Пошив, монтаж и подключение карниза',1,'компл.',None,None,'запрос КП','Салон + монтажник',None)]
cost.extend(extras)
def money(v):return '—' if v is None else f'{v:,.2f}'.replace(',',' ').replace('.',',')
totals=defaultdict(float)
for r in cost:
    if r[6] is not None:totals[r[1]]+=r[6]
assert abs(sum(totals.values())-sum(r[6] for r in cost if r[6] is not None))<.011
head(19,'Приложение · исторические предложения от 09.11 и подбор шторы от 18.11.2026','Бюджет по группам · BYN')
